const STAPLES=new Set(['sel','poivre','huile olive','huile','vinaigre','sucre','eau','ail','oignon','herbes de provence']);
function isStaple(name=''){
const custom=Array.isArray(state.prefs.staples)?state.prefs.staples:[];return STAPLES.has(ingredientKey(name))||custom.some(x=>ingredientKey(x)===ingredientKey(name))}
function ingredientKey(name=''){let n=normText(name);return ING_ALIASES[n]||n.replace(/s$/,'')}
const SUBSTITUTES={
  'creme fraiche':['yaourt nature','creme liquide'],
  'beurre':['huile olive','huile'],
  'parmesan':['gruyere','emmental','fromage rape'],
  'gruyere':['emmental','comte','parmesan'],
  'poulet':['dinde'],
  'dinde':['poulet'],
  'lait':['lait vegetal'],
  'yaourt':['fromage blanc'],
  'oignon':['echalote'],
  'citron':['vinaigre'],
  'persil':['ciboulette'],
  'basilic':['persil']
};
function availableSubstitutes(ingredient){const key=ingredientKey(ingredient);return (SUBSTITUTES[key]||[]).filter(x=>stockHave(x)).slice(0,2)}
function unitBase(unit=''){const u=normText(unit);if(['kg','kilo','kilos'].includes(u))return 'g';if(['g','gramme','grammes'].includes(u))return 'g';if(['l','litre','litres'].includes(u))return 'ml';if(['ml','millilitre','millilitres'].includes(u))return 'ml';if(['cl','centilitre','centilitres'].includes(u))return 'ml';if(['piece','pieces','unite','unites','gousse','gousses'].includes(u))return 'piece';if(['cs','c a soupe','cuillere a soupe','cuilleres a soupe'].includes(u))return 'cs';if(['cc','c a cafe','cuillere a cafe','cuilleres a cafe'].includes(u))return 'cc';return u}
function qtyBase(q,unit){const n=Number(q);if(!Number.isFinite(n))return null;const u=normText(unit);if(['kg','kilo','kilos'].includes(u))return n*1000;if(['l','litre','litres'].includes(u))return n*1000;if(['cl','centilitre','centilitres'].includes(u))return n*10;return n}
function compatibleUnits(a,b){return unitBase(a)===unitBase(b)}
function stockMatches(ingredient,products=state.stock){const key=ingredientKey(ingredient);return products.filter(p=>ingredientKey(p.name)===key&&Number(p.qty)>0)}
function stockMatch(ingredient,products=state.stock){return stockMatches(ingredient,products)[0]||null}
function stockHave(ingredient){return stockMatches(ingredient).length>0}
function stockQuantity(ingredient,unit=null){const matches=stockMatches(ingredient).filter(p=>!unit||compatibleUnits(p.unit,unit));let total=0;for(const p of matches){const q=qtyBase(p.qty,p.unit);if(q!=null)total+=q}return total}
function ingredientNeed(ingredient){const q=qtyBase(ingredient[1],ingredient[2]); return q==null?0:q}
function ingredientCoverage(ingredient){if(isStaple(ingredient?.[0]))return 1;const need=ingredientNeed(ingredient); if(!need)return stockHave(ingredient)?1:0; const have=stockQuantity(ingredient[0],ingredient[2]); return Math.max(0,Math.min(1,have/need))}
function formatQty(n){return Number.isInteger(n)?String(n):Number(n.toFixed(2)).toString()}
function stepDurationSeconds(step=''){
  const s=String(step).toLowerCase();
  let m=s.match(/(\d+)\s*(?:à|a|-)\s*(\d+)\s*(?:min|minutes?)/); if(m)return Number(m[2])*60;
  m=s.match(/(\d+)\s*(?:min|minutes?)/); if(m)return Number(m[1])*60;
  m=s.match(/(\d+)\s*(?:sec|secondes?)/); if(m)return Number(m[1]);
  return 0;
}
function stepTimerLabel(step=''){const sec=stepDurationSeconds(step);return sec?`⏱ ${Math.round(sec/60)} min`:''}
