function releaseWakeLock(){try{wakeLock?.release()}catch(e){}wakeLock=null}

function stockStatus(p){if(!p?.expiry)return 'good';const d=daysTo(p.expiry);return d<0?'danger':d<=1?'danger':d<=4?'warn':'good'}
function statusText(p){if(!p?.expiry)return 'Aucune date limite';const d=daysTo(p.expiry);if(d<0)return 'Expiré';if(d===0)return "Expire aujourd'hui";if(d===1)return 'Expire demain';if(d<=4)return `Dans ${d} jours`;return `Dans ${d} jours`}
function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{db=r.result;['stock','shopping','history','waste','meta'].forEach(s=>{if(!db.objectStoreNames.contains(s))db.createObjectStore(s,{keyPath:'id'})});};r.onsuccess=()=>{db=r.result;res()};r.onerror=()=>rej(r.error)})}
function tx(store,mode='readonly'){return db.transaction(store,mode).objectStore(store)}
async function all(store){return new Promise((res,rej)=>{const r=tx(store).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function put(store,obj){return new Promise((res,rej)=>{const r=tx(store,'readwrite').put(obj);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
async function del(store,id){return new Promise((res,rej)=>{const r=tx(store,'readwrite').delete(id);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
