async function metaSet(id,value){return put('meta',{id,value})}
async function load(){state.stock=await all('stock');state.shopping=await all('shopping');state.history=await all('history');state.waste=await all('waste');const [favorites,feedback,prefs,planning,planningServings,onboardingDone,cookingSession]=await Promise.all([metaGet('favorites'),metaGet('feedback'),metaGet('prefs'),metaGet('planning'),metaGet('planningServings'),metaGet('onboardingDone'),metaGet('cookingSession')]);state.favorites=Array.isArray(favorites)?favorites:[];state.feedback=feedback&&typeof feedback==='object'?feedback:{};state.prefs={...state.prefs,...(prefs||{})};state.prefs.equipment=Array.isArray(state.prefs.equipment)?state.prefs.equipment:['plaques','four','micro-ondes'];state.prefs.likes=Array.isArray(state.prefs.likes)?state.prefs.likes:[];state.prefs.dislikes=Array.isArray(state.prefs.dislikes)?state.prefs.dislikes:[];state.prefs.defaultServings=Math.max(1,Math.min(20,Number(state.prefs.defaultServings)||2));state.prefs.budget=Math.max(0,Number(state.prefs.budget)||60);state.prefs.diet=state.prefs.diet||'Tout';state.prefs.staples=Array.isArray(state.prefs.staples)?state.prefs.staples:['sel','poivre','huile olive','huile','vinaigre','sucre','eau','ail','oignon','herbes de provence'];state.planning=planning&&typeof planning==='object'?planning:{};state.planningServings=planningServings&&typeof planningServings==='object'?planningServings:{};state.planningServings=Object.fromEntries(Object.entries(state.planningServings).filter(([k,v])=>/^[0-6]:[01]$/.test(k)&&Number.isFinite(Number(v))&&Number(v)>=1&&Number(v)<=20&&state.planning?.[k.split(':')[0]]?.[Number(k.split(':')[1])]).map(([k,v])=>[k,Math.round(Number(v))]));state.cookingSession=cookingSession&&typeof cookingSession==='object'?cookingSession:null;state.firstRun=!onboardingDone;document.body.classList.toggle('dark',state.prefs.theme==='dark');}
async function saveStock(p){await put('stock',p);state.stock=await all('stock')}
async function saveHistory(h){const item={id:uid('hist'),...h};await put('history',item);state.history=await all('history');return item.id}
