function money(n){return `${Number(n||0).toFixed(2).replace('.',',')} €`}
function healthGrade(r){
  const text=(r.title+' '+r.category+' '+(r.tags||[]).join(' ')+' '+r.ingredients.map(i=>i[0]).join(' ')).toLowerCase();
  let pts=55;
  const veg=/(tomate|carotte|courgette|brocoli|épinard|salade|poivron|aubergine|champignon|haricot vert|pois|lentille|chou|concombre|courge|fruit|pomme|banane|fraise|framboise|citron|orange|oignon)/;
  const whole=/(complet|semi-complet|avoine|quinoa|lentille|pois chiche|haricot|riz complet)/;
  const lean=/(poulet|dinde|poisson|saumon|thon|œuf|oeuf|tofu)/;
  const rich=/(crème|beurre|fromage|parmesan|mozzarella|lardon|bacon|saucisse|charcut|frit|friture|mayonnaise)/;
  const sweet=/(sucre|sirop|chocolat|pâtisserie|gateau|gâteau|bonbon|caramel|dessert)/;
  const alcohol=/(vin|bière|rhum|whisky|vodka|gin|liqueur|alcool)/;
  const vegCount=r.ingredients.filter(i=>veg.test(i[0].toLowerCase())).length;
  if(vegCount>=2) pts+=18; else if(vegCount===1) pts+=8;
  if(whole.test(text)) pts+=8;
  if(lean.test(text)) pts+=5;
  if(rich.test(text)) pts-=12;
  if(sweet.test(text)) pts-=10;
  if(alcohol.test(text)) pts-=3;
  if((r.time||0)>60) pts-=2;
  if((r.tags||[]).includes('équilibré')) pts+=8;
  pts=Math.max(0,Math.min(100,pts));
  const grade=pts>=80?'A':pts>=65?'B':pts>=50?'C':pts>=35?'D':'E';
  const reasons=[]; if(vegCount>=2)reasons.push('plusieurs végétaux'); else if(vegCount===1)reasons.push('un apport végétal'); if(whole.test(text))reasons.push('céréales complètes ou légumineuses'); if(lean.test(text))reasons.push('source de protéines'); if(rich.test(text))reasons.push('ingrédients riches en matières grasses'); if(sweet.test(text))reasons.push('sucre/dessert'); if(alcohol.test(text))reasons.push('alcool'); return {grade,score:pts,reasons};
}
function profileType(){
  const h=state.history;
  if(h.length<3) return {title:'Profil en construction',desc:'Mon Frigo commence à apprendre tes habitudes. Le profil deviendra plus fiable après quelques repas.',traits:['Découverte','Profil évolutif'],confidence:Math.min(25,Math.round(h.length/3*25)),sample:h.length};
  const avgTime=h.reduce((a,x)=>a+(Number(x.time)||0),0)/h.length;
  const avgCost=h.reduce((a,x)=>a+(Number(x.cost)||0),0)/h.length;
  const ratings=h.filter(x=>Number(x.rating)>0);
  const avgRating=ratings.length?ratings.reduce((a,x)=>a+Number(x.rating),0)/ratings.length:0;
  const usedSoon=h.filter(x=>x.usedSoon||x.savedWaste).length/h.length; const wasteRate=h.length?Math.min(1,state.waste.length/h.length):0; const waste=Math.max(0,usedSoon-wasteRate*0.5);
  const quick=avgTime>0&&avgTime<=25, budget=avgCost>0&&avgCost<=4, anti=waste>=.25, gourmand=avgRating>=4.2;
  let title='Cuisine équilibrée',desc='Tu sembles chercher un bon compromis entre plaisir, simplicité et organisation.',traits=[];
  if(quick&&budget){title='Pratique & économique';desc='Tu privilégies les repas simples, rapides et raisonnables en coût.';traits=['Rapide','Budget','Efficace'];}
  else if(quick){title='Cuisine express';desc='Ton profil montre une préférence pour les repas rapides et faciles à intégrer au quotidien.';traits=['Rapide','Simple','Pratique'];}
  else if(anti){title='Anti-gaspi organisé';desc='Tu utilises volontiers ton stock et sembles attentif à éviter les produits oubliés.';traits=['Anti-gaspillage','Organisation','Stock'];}
  else if(gourmand){title='Gourmand curieux';desc='Tu accordes beaucoup d’importance au plaisir et aux recettes que tu apprécies vraiment.';traits=['Plaisir','Favoris','Découverte'];}
  else if(avgTime>45){title='Cuisine plaisir';desc='Tu sembles accepter de consacrer du temps à la cuisine quand la recette en vaut la peine.';traits=['Cuisine maison','Plaisir','Patience'];}
  const confidence=Math.min(100,Math.round(20+(Math.min(h.length,20)/20)*55+(Math.min(ratings.length,10)/10)*25));
  return {title,desc,traits,confidence,sample:h.length,avgTime,avgCost,avgRating,waste};
}
function score(r){
  let s=30,why=[];
  const meaningful=r.ingredients.filter(i=>!STAPLES.has(ingredientKey(i[0])));
  const cover=meaningful.map(ingredientCoverage);
  const ratio=meaningful.length?cover.reduce((a,x)=>a+x,0)/meaningful.length:1;
  s+=Math.round(ratio*45);
  const missing=meaningful.filter(i=>ingredientCoverage(i)<0.999);
  const complete=meaningful.filter(i=>ingredientCoverage(i)>=0.999);
  if(!missing.length)why.push('tu as tout ce qu’il faut');
  else if(ratio>=.6)why.push(`${complete.length}/${meaningful.length} ingrédients disponibles`);
  const soon=meaningful.some(i=>stockMatches(i[0]).filter(p=>compatibleUnits(p.unit,i[2])).some(p=>daysTo(p.expiry)<=4));
  if(soon){s+=10;why.push('utilise un produit à consommer bientôt')}
  if(r.time<=20){s+=5;why.push('très rapide')}
  const equipment=Array.isArray(r.equipment)?r.equipment:[];
  if(Array.isArray(state.prefs.equipment)&&state.prefs.equipment.length){const ok=equipment.every(e=>e==='aucun'||state.prefs.equipment.includes(e));if(ok){s+=5;why.push('équipement disponible')}else{s-=25;why.push('il manque un équipement')}}
  const hist=state.history.filter(h=>h.recipeId===r.id);
  if(state.favorites.includes(r.id)){s+=5;why.push('dans tes favoris')}
  if(hist.length){const rated=hist.filter(h=>Number(h.rating)>0);const avg=rated.length?rated.reduce((a,h)=>a+Number(h.rating),0)/rated.length:0;const confidence=Math.min(1,rated.length/3);const ratingEffect=Math.round((avg-3)*5*confidence);s+=ratingEffect;if(avg>=4&&confidence>=.66)why.push('tu as aimé cette recette');if(avg<=2&&confidence>=.66){s-=Math.round(8*confidence);why.push('tes notes récentes sont plutôt basses')}else if(rated.length===1){why.push('apprentissage encore prudent')}const last=hist.slice().sort((a,b)=>new Date(b.date)-new Date(a.date))[0];if(last&&Date.now()-new Date(last.date).getTime()<3*86400000){s-=10;why.push('déjà mangée récemment')}}
  if(r.tags?.includes('anti-gaspillage')&&soon){s+=3;why.push('bon candidat anti-gaspi')}
  const recentIds=new Set(state.history.filter(h=>Date.now()-new Date(h.date).getTime()<14*86400000).map(h=>h.recipeId));
  if(recentIds.has(r.id)){const recentPenalty=hist.length>=2?10:6;s-=recentPenalty;why.push('varie tes repas récents')}
  const weeklyBudget=Number(state.prefs.budget)||60;if(r.cost>weeklyBudget/2){s-=4;why.push('un peu au-dessus de ton budget habituel')}
  const hour=new Date().getHours(), meal=(r.mealTypes||[]);
  const currentMeal=hour>=6&&hour<11?'Petit-déjeuner':hour>=11&&hour<15?'Déjeuner':hour>=18&&hour<22?'Dîner':'Tous';
  if(currentMeal!=='Tous'&&meal.includes(currentMeal)){s+=5;why.push(`adaptée au ${currentMeal.toLowerCase()}`)}
  const recentCats=new Set(state.history.filter(h=>Date.now()-new Date(h.date).getTime()<7*86400000).map(h=>state.recipes.find(x=>x.id===h.recipeId)?.category).filter(Boolean));
  if(r.category&&recentCats.has(r.category)){s-=3;why.push('apporte un peu de variété')}
  if((r.cuisine||'')&&state.history.length>=4){const recentCuisine=new Set(state.history.slice(-8).map(h=>state.recipes.find(x=>x.id===h.recipeId)?.cuisine).filter(Boolean));if(recentCuisine.has(r.cuisine)){s-=2}else{s+=2;why.push('change de cuisine')}}
  const planned=Object.values(state.planning||{}).flat().filter(Boolean);
  const plannedRecipes=planned.map(id=>state.recipes.find(x=>x.id===id)).filter(Boolean);
  const plannedCount=plannedRecipes.length;
  if(plannedCount){
    const sameRecipe=plannedRecipes.filter(x=>x.id===r.id).length;
    const sameCategory=plannedRecipes.filter(x=>x.category&&x.category===r.category).length;
    const sameCuisine=plannedRecipes.filter(x=>x.cuisine&&x.cuisine===r.cuisine).length;
    if(sameRecipe){s-=18;why.push('déjà prévue cette semaine')}
    else if(sameCategory>=2){s-=7;why.push('varie les catégories de la semaine')}
    else if(sameCategory===1){s-=2}
    if(r.cuisine&&sameCuisine>=2){s-=5;why.push('varie les cuisines cette semaine')}
  }
  const diet=state.prefs.diet||'Tout';
  const meat=/(poulet|dinde|boeuf|bœuf|veau|porc|jambon|lardon|bacon|saucisse|viande|agneau|canard)/.test(r.ingredients.map(i=>normText(i[0])).join(' '));
  const fish=/(saumon|thon|poisson|crevette|crevettes|cabillaud|truite|moule|moules|fruits de mer)/.test(r.ingredients.map(i=>normText(i[0])).join(' '));
  if(diet==='Végétarien'&&meat){s-=55;why.push('ne correspond pas à ton alimentation végétarienne')}
  if(diet==='Pescétarien'&&meat){s-=55;why.push('contient de la viande')}
  if(diet==='Pescétarien'&&fish){s+=3;why.push('compatible avec ton alimentation')}
  if(diet==='Sans porc'&&/(porc|jambon|lardon|bacon|saucisse)/.test(r.ingredients.map(i=>normText(i[0])).join(' '))){s-=55;why.push('contient du porc')}
  const likes=(state.prefs.likes||[]).map(ingredientKey),dislikes=(state.prefs.dislikes||[]).map(ingredientKey),titleKey=ingredientKey(r.title);
  if(likes.some(x=>titleKey.includes(x)||r.ingredients.some(i=>ingredientKey(i[0]).includes(x)))){s+=6;why.push('correspond à tes goûts')}
  if(dislikes.some(x=>titleKey.includes(x)||r.ingredients.some(i=>ingredientKey(i[0]).includes(x)))){s-=30;why.push('contient un aliment que tu évites')}
  if(state.feedback?.[r.id]?.notInterested){s-=22;why.push('tu as indiqué ne pas vouloir cette recette')}
  if(state.feedback?.[r.id]?.reported){s-=60;why.push('tu as signalé un problème avec cette recette')}
  if(r.quality?.status==='verified'){s+=5;why.push('recette vérifiée')}else if(r.quality?.status==='curated'){s+=3;why.push('sélection Mon Frigo')}
  return {score:Math.max(0,Math.min(99,s)),why,missing};
}
async function getRecipeDetails(id){
  const cached=state.recipeDetails.get(id);if(cached)return cached;
  const meta=state.recipes.find(r=>r.id===id);if(!meta)return null;
  if(meta.steps){state.recipeDetails.set(id,meta);return meta}
  try{if(Array.isArray(window.MON_FRIGO_EMBEDDED_RECIPES)){const full=window.MON_FRIGO_EMBEDDED_RECIPES.find(r=>r.id===id);if(full){state.recipeDetails.set(id,full);return full}}const data=await fetch(`./data/recipe-chunks/${meta.chunk}.json`).then(r=>r.json());data.forEach(r=>state.recipeDetails.set(r.id,r));return state.recipeDetails.get(id)||meta}catch(e){return meta}
}
function recommendation(){
  let list=state.recipes.map(r=>({r,...score(r)})).filter(x=>!state.feedback?.[x.r.id]?.reported).filter(x=>x.r.equipment.every(e=>e==='aucun'||state.prefs.equipment.includes(e)));
  if(!list.length)list=state.recipes.map(r=>({r,...score(r)}));
  list.sort((a,b)=>b.score-a.score);
  const chosen=[];const usedCat=new Set();const usedCuisine=new Set();
  for(const x of list){
    const cat=x.r.category||'Autre';
    const same=usedCat.has(cat);const cuisine=x.r.cuisine||'';const sameCuisine=cuisine&&usedCuisine.has(cuisine);
    const penalty=(same?8:0)+(sameCuisine?4:0);
    if(chosen.length<2 || x.score-penalty>=chosen[chosen.length-1].score-3){
      if((!same&&!sameCuisine)||chosen.length<2){chosen.push(x);usedCat.add(cat);if(cuisine)usedCuisine.add(cuisine);if(chosen.length===3)break;}
    }
  }
  if(chosen.length<3){for(const x of list)if(!chosen.some(y=>y.r.id===x.r.id)){chosen.push(x);if(chosen.length===3)break;}}
  return chosen;
}
function render(){const v=$('#view'); if(state.tab==='home')v.innerHTML=home(); if(state.tab==='stock')v.innerHTML=stock(); if(state.tab==='recipes')v.innerHTML=recipes(); if(state.tab==='shopping')v.innerHTML=shopping(); if(state.tab==='me')v.innerHTML=me();bind();}
