function labelEquipment(e){return {'plaques':'Plaques','four':'Four','micro-ondes':'Micro-ondes','air_fryer':'Air Fryer','thermomix':'Thermomix','mixeur':'Mixeur','blender':'Blender','gaufrier':'Gaufrier'}[e]||e}
document.addEventListener('visibilitychange',async()=>{if(document.visibilityState==='visible'&&state.cooking)await requestWakeLock()});
function globalSearchModal(){
  let q='';
  function draw(){
    const n=normText(q);
    const recipeHits=!n?[]:state.recipes.filter(r=>normText(r.title).includes(n)||(r.ingredients||[]).some(i=>normText(i[0]).includes(n))).slice(0,8);
    const stockHits=!n?[]:state.stock.filter(x=>normText(x.name).includes(n)).slice(0,6);
    const shoppingHits=!n?[]:state.shopping.filter(x=>normText(x.name).includes(n)).slice(0,6);
    modal('Rechercher dans Mon Frigo',`<div class="stack"><input class="search" id="globalSearch" autofocus placeholder="Recette, ingrédient, produit…" value="${esc(q)}"><div class="muted" style="font-size:11px">Recherche dans tes recettes, ton stock et tes courses.</div>${!n?`<div class="card empty"><strong>Commence à taper.</strong><div>Ex. « poulet », « tomates », « pâtes »…</div></div>`:''}${n&&recipeHits.length?`<div><div class="smallcaps">Recettes · ${recipeHits.length}</div><div class="stack" style="margin-top:8px">${recipeHits.map(r=>`<button class="card" data-global-recipe="${esc(r.id)}" style="text-align:left"><div class="row"><span class="food-icon">${recipeEmoji(r)}</span><div class="grow"><b>${esc(r.title)}</b><div class="sub">${r.time} min · ${r.difficulty}</div></div><span>›</span></div></button>`).join('')}</div></div>`:''}${n&&stockHits.length?`<div><div class="smallcaps">Mon stock · ${stockHits.length}</div><div class="stack" style="margin-top:8px">${stockHits.map(x=>`<button class="card" data-global-stock="${esc(x.id)}" style="text-align:left"><div class="row"><span class="food-icon">${emojiFor(x.name)}</span><div class="grow"><b>${esc(x.name)}</b><div class="sub">${esc(x.qty)} ${esc(x.unit)} · ${statusText(x)}</div></div><span>›</span></div></button>`).join('')}</div></div>`:''}${n&&shoppingHits.length?`<div><div class="smallcaps">Mes courses · ${shoppingHits.length}</div><div class="stack" style="margin-top:8px">${shoppingHits.map(x=>`<button class="card" data-global-shopping="${esc(x.id)}" style="text-align:left"><div class="row"><span class="food-icon">🛒</span><div class="grow"><b>${esc(x.name)}</b><div class="sub">${esc(x.qty||'')} ${esc(x.unit||'')} · ${x.done?'acheté':'à acheter'}</div></div><span>›</span></div></button>`).join('')}</div></div>`:''}${n&&!recipeHits.length&&!stockHits.length&&!shoppingHits.length?`<div class="card empty"><strong>Aucun résultat.</strong><div>Essaie un autre mot ou une autre formulation.</div></div>`:''}<button class="btn ghost wide" data-close>Fermer</button></div>`);
    const input=$('#globalSearch');
    if(input){input.oninput=()=>{q=input.value;draw();setTimeout(()=>{$('#globalSearch')?.focus();$('#globalSearch')?.setSelectionRange(q.length,q.length)},0)}}
    $$('[data-global-recipe]').forEach(b=>b.onclick=async()=>{const id=b.dataset.globalRecipe;closeModal();await recipeModal(id)});
    $$('[data-global-stock]').forEach(b=>b.onclick=()=>{closeModal();state.tab='stock';render();setTimeout(()=>{$('#stockSearch')?.focus();$('#stockSearch').value=state.stock.find(x=>x.id===b.dataset.globalStock)?.name||'';$('#stockSearch').dispatchEvent(new Event('input'))},0)});
    $$('[data-global-shopping]').forEach(b=>b.onclick=()=>{closeModal();state.tab='shopping';render()});
  }
  draw();
}
